MOD = 1_000_000_007


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    idx = {ch: i for i, ch in enumerate(alphabet)}
    k = len(alphabet)

    # Build the Aho-Corasick trie. bad[u] marks a node that completes a banned string.
    goto = [[-1] * k]
    bad = [False]
    for word in banned:
        node = 0
        for ch in word:
            c = idx[ch]
            if goto[node][c] == -1:
                goto[node][c] = len(goto)
                goto.append([-1] * k)
                bad.append(False)
            node = goto[node][c]
        bad[node] = True

    # BFS: build failure links, complete transitions, propagate bad flags.
    fail = [0] * len(goto)
    queue = []
    for c in range(k):
        if goto[0][c] == -1:
            goto[0][c] = 0
        else:
            fail[goto[0][c]] = 0
            queue.append(goto[0][c])

    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1
        bad[u] = bad[u] or bad[fail[u]]
        for c in range(k):
            v = goto[u][c]
            if v == -1:
                goto[u][c] = goto[fail[u]][c]
            else:
                fail[v] = goto[fail[u]][c]
                queue.append(v)

    # Keep only safe states (the root is always safe since banned strings are non-empty).
    states = [u for u in range(len(goto)) if not bad[u]]
    pos = {u: i for i, u in enumerate(states)}
    m = len(states)

    # Transition matrix: M[i][j] = number of characters moving safe state i to safe state j.
    M = [[0] * m for _ in range(m)]
    for u in states:
        for c in range(k):
            v = goto[u][c]
            if not bad[v]:
                M[pos[u]][pos[v]] += 1

    def mat_mul(A: list[list[int]], B: list[list[int]]) -> list[list[int]]:
        size = len(A)
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            Ai = A[i]
            Ci = C[i]
            for t in range(size):
                a = Ai[t]
                if a:
                    Bt = B[t]
                    for j in range(size):
                        Ci[j] += a * Bt[j]
            for j in range(size):
                Ci[j] %= MOD
        return C

    # Compute the row vector from the root times M^n by binary exponentiation.
    vec = [0] * m
    vec[pos[0]] = 1
    while n:
        if n & 1:
            vec = [sum(vec[i] * M[i][j] for i in range(m)) % MOD for j in range(m)]
        n >>= 1
        if n:
            M = mat_mul(M, M)

    return sum(vec) % MOD
